import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class Main {public static void main(String[]a)throws Exception{ExecutorService pool=Executors.newFixedThreadPool(3);AtomicInteger successes=new AtomicInteger(),failures=new AtomicInteger();for(int i=1;i<=10;i++){final int job=i;pool.submit(()->{try{if(job%4==0)throw new IllegalStateException("simulated job fault");successes.incrementAndGet();System.out.println("Processed job "+job);}catch(RuntimeException e){failures.incrementAndGet();System.err.println("Job "+job+" failed: "+e.getMessage());}});}pool.shutdown();pool.awaitTermination(5,TimeUnit.SECONDS);System.out.println("Success="+successes+", failures="+failures);}}
